Certainly! Below is a Go program that takes the name of a Go source file and the name of a struct as input parameters. The program then reads the contents of the specified Go source file, parses the struct definition using `reflect`, generates an Avro schema based on that struct, and outputs the generated Avro schema to a file with the `.avsc` extension.

```go
package main

import (
	"bufio"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"

	"github.com/google/go-jsonschema2avro/schema"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run script.go <input_file> <struct_name>")
		os.Exit(1)
	}

	inputFile := os.Args[1]
	structName := os.Args[2]

	file, err := os.Open(inputFile)
	if err != nil {
		fmt.Printf("Error opening file: %v\n", err)
		return
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := scanner.Text()
		ast.Walk(func(node ast.Node) error {
			switch n := node.(type) {
			case *ast.TypeSpec:
				if _, ok := n.Name.Value; !ok {
					continue // Skip if not a struct type
				}
				if n.Name.Value == structName {
					parsedType := reflect.TypeOf(n.Type)
					var jsonSchema schema.JsonSchema
					if parsedType.Kind() == reflect.Struct {
						jsonSchema = schema.GenerateFromReflect(parsedType)
					} else {
						fmt.Printf("Unsupported type for struct: %s\n", parsedType)
						return nil
					}
					schemaPath := filepath.Join(filepath.Dir(inputFile), fmt.Sprintf("%s.avsc", structName))
					err := schema.WriteToFile(jsonSchema, schemaPath)
					if err != nil {
						fmt.Printf("Failed to write Avro schema to file: %v\n", err)
						return err
					}
					fmt.Printf("Avro schema written to: %s\n", schemaPath)
					return nil
				}
			default:
				// Continue walking through other nodes (e.g., functions, imports)
			}
		})
	}
	if err := scanner.Err(); err != nil {
		fmt.Printf("Scan error: %v\n", err)
	}
}
```

### How to Use the Program

1. **Compile the Program**: Save this code into a file named `script.go`. Then compile it using the following command:
   ```sh
   go build -o script script.go
   ```

2. **Run the Program**: When you run the compiled executable, provide the path to your Go source file and the name of the struct you want to convert. For example:
   ```sh
   ./script /path/to/your/source/file.go MyStruct
   ```

This will read the specified Go source file, find all structs, check which one matches the provided struct name, and generate an Avro schema for that struct.

### Notes:

- This program assumes that the struct has a valid Go syntax. If the struct does not have a valid Go syntax or if it's part of a package, additional handling might be required.
- The program uses `reflect` to get the type information and `jsonschema2avro/schema` to generate the Avro schema. Ensure these dependencies are installed in your environment.

